head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getFocusedFooterID]<br/>focusFooter=true 일때 포커스된 모든 Footer Cell 의 ID 값을 배열로 반환합니다.",
    "validation" : [
        "포커스된 모든 Footer Cell 의 ID 값을 1차원 배열로 반환하여야 합니다.",
        "반환되는 배열은 Footer Cell 을 포커스 한 순서에 맞게 생성되어야 합니다.",
        "포커스된 Footer Cell 이 없는 경우 빈 배열을 반환하여야 합니다.",
        "Shift 키를 이용하여 여러 Footer Cell 을 포커스 할 수 있어야 합니다.",
        "Shift 키를 이용하여 여러 Footer Cell 을 포커스 시 숨겨진 Footer Cell 도 포커스 상태로 처리되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (focusFooter, Footer 2줄, 두번째 Column 숨김)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" focusFooter="true" useShiftKey="true" checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft1" value="footer1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft2" value="footer2(H)" hidden="true"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft3" value="footer3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft4" value="footer4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="row4">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft5" value="footer5"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft6" value="footer6(H)" hidden="true"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft7" value="footer7"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft8" value="footer8"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



scwin.btn_getFocusedFooterID_onclick = function () {
    let rtn = target1.getFocusedFooterID();
    wf_body_bottom.getObj("scwin").setReturnValue("getFocusedFooterID : " + JSON.stringify(rtn));
}
